class Weekday {
  static [Symbol.hasInstance](value) {
    return ["Mon", "Tue", "Wed", "Thu", "Fri"].includes(value);
  }
}

const days = ["Mon", "Sat"];
const extra = { length: 1, 0: "Sun", [Symbol.isConcatSpreadable]: true };

console.log("Mon" instanceof Weekday);
console.log("Sat" instanceof Weekday);
console.log(new Weekday() instanceof Weekday);
console.log(days.concat(extra).join(","));
